/*
 * diagnostic_font.h - the built-in 8x16 font of the Stage 3 diagnostic output.
 *
 * Purpose:
 *   The pictures of the characters that diagnostic_output.c draws on the
 *   framebuffer. Printable ASCII only (0x20 to 0x7E).
 *
 * Limitations:
 *   The glyph data (diagnostic_font.c) is generated by scripts/gen_font.py;
 *   do not edit it by hand. Private to src/boot.
 */

#ifndef JUSTOS_BOOT_DIAGNOSTIC_FONT_H
#define JUSTOS_BOOT_DIAGNOSTIC_FONT_H

#include <stdint.h>

#define JP_DIAGNOSTIC_FONT_WIDTH 8
#define JP_DIAGNOSTIC_FONT_HEIGHT 16
#define JP_DIAGNOSTIC_FONT_FIRST_CHAR 0x20
#define JP_DIAGNOSTIC_FONT_LAST_CHAR 0x7E
#define JP_DIAGNOSTIC_FONT_GLYPH_COUNT (JP_DIAGNOSTIC_FONT_LAST_CHAR - JP_DIAGNOSTIC_FONT_FIRST_CHAR + 1)

/* Row y of the glyph (c - FIRST_CHAR): bit 7 is the leftmost pixel. */
extern const uint8_t jp_diagnostic_font8x16[JP_DIAGNOSTIC_FONT_GLYPH_COUNT][JP_DIAGNOSTIC_FONT_HEIGHT];

#endif /* JUSTOS_BOOT_DIAGNOSTIC_FONT_H */
